begin;
create table if not exists public.naczynia (id bigint generated by default as identity primary key, created_at timestamptz not null default now(), nazwa text not null unique check(length(trim(nazwa))>0), gramy double precision not null check(gramy>0));
create table if not exists public.porcje_produktow (id bigint generated by default as identity primary key, created_at timestamptz not null default now(), produkt_id bigint not null references public.produkty(id) on delete cascade, nazwa text not null check(length(trim(nazwa))>0), gramy double precision not null check(gramy>0), unique(produkt_id,nazwa));
alter table public.naczynia enable row level security; alter table public.porcje_produktow enable row level security;
grant select,insert,update,delete on public.naczynia,public.porcje_produktow to authenticated; revoke all on public.naczynia,public.porcje_produktow from anon;
drop policy if exists "Zalogowani zarzadzaja naczyniami" on public.naczynia; create policy "Zalogowani zarzadzaja naczyniami" on public.naczynia for all to authenticated using(true) with check(true);
drop policy if exists "Zalogowani zarzadzaja porcjami produktow" on public.porcje_produktow; create policy "Zalogowani zarzadzaja porcjami produktow" on public.porcje_produktow for all to authenticated using(true) with check(true);
commit;
